import React from "react";
import { Helmet } from "react-helmet";

import { AppContext } from "../context";
import { AppDashboard, AppCleverForms, AppDocumentSignatures, AppMyPay, AppAnnouncement } from "./config";
import { NoMatch } from "./NoMatch";

interface Props {
    name: string;
    label: string;
}

export const RenderAvailableConfig: React.FC<Props> = ({ name, label }) => {
    const { state } = React.useContext(AppContext);

    const setConfigContent = () => {
        switch (name) {
            case "Dashboard":
                return state.dashboardLinks.length ? <AppDashboard /> : null;

            case "MyPay":
                return <AppMyPay />;

            case "DocumentSignatures":
                return <AppDocumentSignatures />;

            case "CleverForms":
                return <AppCleverForms />;

            case "Announcements":
                return <AppAnnouncement />;

            default:
                return <NoMatch />;
        }
    };

    return (
        <>
            <Helmet>
                <title>{label} Configuration</title>
            </Helmet>
            <div className="ss-app-config-wrap">{setConfigContent()}</div>
        </>
    );
};
