import { Dropdown } from "antd";
import React from "react";
import { ICON_ASSETS } from "../types";
import { AppIcon } from "./SVGFiles";

interface IconSelectProps {
    value?: string;
    disabled?: boolean;
    onChange?: (value: string) => void;
}

export const IconSelect: React.FC<IconSelectProps> = ({ value = "", onChange, disabled = false }) => {
    const [icon, setIcon] = React.useState("");
    const [showPopup, setShowPopup] = React.useState(false);

    React.useEffect(() => {
        if (value) {
            setIcon(value);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    React.useEffect(() => {
        if (showPopup) {
            document.body.classList.add("freeze");
        } else document.body.classList.remove("freeze");
    }, [showPopup]);

    const triggerChange = (icon: string) => {
        onChange && onChange(icon);
    };

    const onIconChange = (newIcon: string) => {
        if (newIcon) {
            setIcon(newIcon);
        }
        triggerChange(newIcon);
    };

    const iconSet = () => (
        <div className="ss-app-config-icon-set">
            <div className="ss-app-config-icon-set-wrap">
                {ICON_ASSETS.map((icon) => (
                    <div
                        className="ss-app-config-icon-item"
                        onClick={() => {
                            onIconChange(icon);
                            setShowPopup(false);
                        }}>
                        <AppIcon asset={icon} height="36" width="36" />
                        <div>{icon}</div>
                    </div>
                ))}
            </div>
        </div>
    );

    return (
        <>
            <div
                className={`ss-app-config-icon-select-overlay${showPopup ? " open" : ""}`}
                onClick={() => setShowPopup(false)}></div>
            <Dropdown
                overlayStyle={{ position: "fixed", zIndex: 99 }}
                overlay={iconSet}
                trigger={["click"]}
                visible={showPopup}
                disabled={disabled}>
                <span className="ss-app-config-icon-selected" onClick={() => setShowPopup(!showPopup)}>
                    {icon ? (
                        <AppIcon asset={icon} height="48" width="48" />
                    ) : (
                        <span className="ss-app-config-icon-select-label">SELECT ICON</span>
                    )}
                    {showPopup ? (
                        <AppIcon asset="arrow-up" height="16" width="16" />
                    ) : (
                        <AppIcon asset="arrow-down" height="16" width="16" />
                    )}
                </span>
            </Dropdown>
        </>
    );
};
